        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans establish both the identity-mismatch relation and its prospective status."
    }
  },
  "signal_basis": {
    "component_id": "C021.signal_basis",
    "value": "Cross-checking order identifiers, suppliers, amounts, scope, people and dates across records reveals mismatched identities.",
    "scope": "Assumed outcome of a proposed check for the order under reconstruction; no mismatch is asserted to have actually occurred.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        },
        {
          "source_id": "P017",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The bundle specifies the cross-check, the possible identity mismatch and the distinction between proposed findings and actual observations."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C021.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is needed for this supported, bounded claim."
    }
  },
  "rationale": "An identity mismatch leaves uncertain whether records concern the same order or participants and therefore whether they can reliably establish its sequence. This licenses the limited uncertainty claim.",
  "uncertainty": "The mismatch does not determine which record is mistaken or whether approval occurred; the claim does not assert either conclusion.",
  "anomalies": []
}
